CREATE EXTENSION IF NOT EXISTS timescaledb;
CREATE TABLE IF NOT EXISTS depots(id text PRIMARY KEY,name text NOT NULL,lat double precision NOT NULL,lon double precision NOT NULL);
CREATE TABLE IF NOT EXISTS drivers(id text PRIMARY KEY,name text NOT NULL,license text UNIQUE NOT NULL,depot_id text REFERENCES depots(id),status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','assigned','driving','unavailable')));
CREATE TABLE IF NOT EXISTS vehicles(id text PRIMARY KEY,registration text UNIQUE NOT NULL,depot_id text REFERENCES depots(id),status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','assigned','moving','paused','breakdown')),capacity integer NOT NULL CHECK(capacity>0),last_ts timestamptz,last_position jsonb);
CREATE TABLE IF NOT EXISTS routes(id text PRIMARY KEY,name text NOT NULL,geometry jsonb NOT NULL,status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','assigned','active','paused','disrupted','completed','cancelled')),vehicle_id text REFERENCES vehicles(id),driver_id text REFERENCES drivers(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS routes_vehicle_active ON routes(vehicle_id) WHERE status IN ('assigned','active','paused','disrupted');
CREATE UNIQUE INDEX IF NOT EXISTS routes_driver_active ON routes(driver_id) WHERE status IN ('assigned','active','paused','disrupted');
CREATE TABLE IF NOT EXISTS deliveries(id text PRIMARY KEY,reference text UNIQUE NOT NULL,customer text NOT NULL,address text NOT NULL,lat double precision NOT NULL CHECK(lat BETWEEN -90 AND 90),lon double precision NOT NULL CHECK(lon BETWEEN -180 AND 180),priority text NOT NULL CHECK(priority IN ('low','normal','high','urgent')),scheduled_at timestamptz NOT NULL,due_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','scheduled','assigned','in_transit','delayed','completed','cancelled')),route_id text REFERENCES routes(id),sequence integer,completed_at timestamptz,outcome text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(due_at>=scheduled_at));
CREATE INDEX IF NOT EXISTS deliveries_route ON deliveries(route_id,sequence);
CREATE INDEX IF NOT EXISTS deliveries_status_due ON deliveries(status,due_at);
CREATE TABLE IF NOT EXISTS assignments(id text PRIMARY KEY,delivery_id text REFERENCES deliveries(id),route_id text REFERENCES routes(id),vehicle_id text REFERENCES vehicles(id),driver_id text REFERENCES drivers(id),assigned_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,reason text NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS assignments_current ON assignments(delivery_id) WHERE ended_at IS NULL;
CREATE TABLE IF NOT EXISTS journeys(id text PRIMARY KEY,route_id text NOT NULL REFERENCES routes(id),vehicle_id text NOT NULL REFERENCES vehicles(id),driver_id text NOT NULL REFERENCES drivers(id),status text NOT NULL CHECK(status IN ('running','paused','stopped','completed')),progress double precision NOT NULL DEFAULT 0,seq bigint NOT NULL DEFAULT 0,scenario text NOT NULL DEFAULT '',started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS journeys_current ON journeys(vehicle_id) WHERE status IN ('running','paused');
CREATE TABLE IF NOT EXISTS telemetry(ts timestamptz NOT NULL,event_id text NOT NULL,vehicle_id text NOT NULL,journey_id text NOT NULL,route_id text NOT NULL,lat double precision NOT NULL,lon double precision NOT NULL,speed double precision NOT NULL,heading double precision NOT NULL,seq bigint NOT NULL,progress double precision NOT NULL,scenario text NOT NULL DEFAULT '',PRIMARY KEY(ts,event_id));
SELECT create_hypertable('telemetry','ts',if_not_exists=>TRUE);
CREATE INDEX IF NOT EXISTS telemetry_vehicle_time ON telemetry(vehicle_id,ts DESC);
CREATE INDEX IF NOT EXISTS telemetry_journey_time ON telemetry(journey_id,ts);
CREATE TABLE IF NOT EXISTS processed_events(event_id text PRIMARY KEY,processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS alerts(id text PRIMARY KEY,vehicle_id text REFERENCES vehicles(id),journey_id text REFERENCES journeys(id),route_id text REFERENCES routes(id),type text NOT NULL,severity text NOT NULL CHECK(severity IN ('warning','critical')),message text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','acknowledged','resolved')),created_at timestamptz NOT NULL DEFAULT now(),acknowledged_at timestamptz,resolved_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS alerts_active_kind ON alerts(journey_id,type) WHERE status <> 'resolved';
CREATE TABLE IF NOT EXISTS alert_history(id bigserial PRIMARY KEY,alert_id text NOT NULL REFERENCES alerts(id),action text NOT NULL,note text NOT NULL,at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(id integer PRIMARY KEY CHECK(id=1),speed double precision NOT NULL DEFAULT 1 CHECK(speed>0 AND speed<=100),deviation_m double precision NOT NULL DEFAULT 350 CHECK(deviation_m>0),stop_seconds integer NOT NULL DEFAULT 20 CHECK(stop_seconds>=2),delay_seconds integer NOT NULL DEFAULT 0 CHECK(delay_seconds>=0),sim_state text NOT NULL DEFAULT 'stopped' CHECK(sim_state IN ('running','paused','stopped')));
INSERT INTO settings(id) VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS stop_tracking(vehicle_id text PRIMARY KEY,since timestamptz NOT NULL);
